{"cards": [{"node_code": "N_9517d29c389fd05a", "definition": "研究利用测量技术获取航道水深、底质、岸线及障碍物数据，为海图编制、航道疏浚及船舶安全航行提供基础地理信息的方法与理论。", "boundary": "本节点聚焦于“测量”过程与数据获取，即如何确定航道空间几何特征。边界在于区分“航道工程”（侧重疏浚、整治等物理改变）和“航海基础科学”（侧重潮汐、水流等自然规律）。若内容涉及测量仪器的硬件制造，归入船舶工程或仪器类；若涉及基于测量数据的海图出版与使用，归入航海资料。", "includes": ["水深测量、地形测量及航道障碍物探测技术", "航道测量数据处理、精度分析及海图底图制作基础", "内河与海洋航道的测量规范与方法"], "excludes": ["航道疏浚、整治等工程施工技术（归入航道工程）", "潮汐、水流等水文现象的理论研究（归入航海基础科学）"], "sibling_distinctions": [{"other_code": "N_6efddb562945a179", "rule": "本节点关注“获取数据”（测量技术），兄弟节点关注“解释现象”（水文、气象等基础科学原理）。"}, {"other_code": "N_5dcd0bbca21a0d20", "rule": "本节点关注“数据生产”（测量过程），兄弟节点关注“数据应用”（海图、航海通告等资料的使用）。"}], "cross_boundary_rule": "若内容涉及测量船的设计与建造，主挂载船舶工程；若涉及测量数据的航海应用，主挂载本节点。"}, {"node_code": "N_bebc26e8e12f6ead", "definition": "研究船舶在特定气象、水文、地理或特殊水域条件下安全航行的策略、操纵技巧及风险规避方法，涵盖狭水道、雾夜、台风等场景。", "boundary": "本节点聚焦于“特定条件”下的航行应对，即非标准或复杂环境中的驾驶决策。边界在于区分“一般航行”（开阔水域常规航行）和“船舶操纵技术”（侧重船舶运动学原理与操纵性分析）。若内容涉及具体气象预报原理，归入航海基础科学；若涉及船舶结构抗风浪设计，归入船舶工程。", "includes": ["狭水道、浅水、内河及沿海近海等特殊水域的航行规则", "雾航、夜航、台风区及大风浪条件下的航行策略", "潜水航行、大圆航行及特种航区的特殊驾驶要求"], "excludes": ["船舶操纵性水动力原理与数学模型（归入船舶操纵技术）", "气象、潮汐等自然现象的基础理论研究（归入航海基础科学）"], "sibling_distinctions": [{"other_code": "N_4c709dbaf9b22849", "rule": "本节点关注“环境适应”（特定条件下的策略），兄弟节点关注“船舶性能”（操纵性、回转性等物理特性）。"}, {"other_code": "N_6efddb562945a179", "rule": "本节点关注“应对策略”（驾驶操作），兄弟节点关注“环境规律”（风、流、潮的科学原理）。"}], "cross_boundary_rule": "若内容涉及特定条件下船舶操纵性的变化分析，主挂载船舶操纵技术；若涉及驾驶人员的决策与操作规范，主挂载本节点。"}, {"node_code": "N_0a2153b9eed35ee9", "definition": "研究确定船舶在地球表面位置的方法与理论，涵盖位置线原理、误差分析，以及利用陆标、天体等手段进行定位的技术。", "boundary": "本节点聚焦于“位置确定”（Where am I?），即通过观测或计算得出船位。边界在于区分“导航”（Where to go?，侧重路径规划与引导）和“航行仪器”（侧重设备本身）。若内容涉及GPS卫星系统原理，归入船舶导航与通信；若涉及海图上的航线规划，归入航海资料或导航。", "includes": ["位置线理论、船位误差分析及定位精度评估", "陆标定位（方位、距离、交叉定位）技术与方法", "天体定位（太阳、恒星、行星）原理与计算"], "excludes": ["电子海图显示与信息系统（ECDIS）的硬件功能（归入航行仪器）", "航线规划、航路设计等导航策略（归入船舶导航与通信）"], "sibling_distinctions": [{"other_code": "N_253238d4186203d2", "rule": "本节点关注“定位”（确定当前位置），兄弟节点关注“导航”（引导至目的地，含通信与路径规划）。"}, {"other_code": "N_d4995ceafb64dfca", "rule": "本节点关注“定位方法”（如何使用仪器或天体），兄弟节点关注“仪器本身”（罗经、雷达等设备的结构与原理）。"}], "cross_boundary_rule": "若内容涉及定位算法在电子海图上的实现，主挂载本节点；若涉及定位设备的硬件故障排除，主挂载航行仪器。"}]}
